      }
    `,
    item_header: css`
    `,
    item_content: css`
      display: flex;
      align-items: center;
      gap: ${token.paddingSM}px;
    `,
    item_icon: css`
      width: 32px;
      height: 32px;
      padding: ${token.paddingSM}px;
      border-radius: ${introRadius / 2}px;
      background: #ffffff1a;
      box-shadow: inset 0px 1px 1.5px 0px #ffffff80;
    `,
    item_title: css`
      display: flex;
      align-items: center;
      gap: ${token.paddingXS}px;
      font-size: ${token.fontSizeHeading4}px;
      font-weight: bold;
      margin-bottom: ${token.paddingXS}px;
    `,
    item_desc: css`
      text-align: start;
      font-size: ${token.fontSizeSM}px;
      opacity: 0.65;
    `,
    item_tag: css`
      border-radius: 4px;
      color: transparent;
      height: 24px;
      line-height: 24px;
      box-sizing: border-box;
      font-size: ${token.fontSizeSM}px;
      padding: 0 8px;
      position: relative;
      overflow: hidden;

      &::before {
        content: '';
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;

        width: 100%;
        height: 100%;

        background: #ffffff;
        opacity: 0.1;
      }
    `,
  };
});

export interface IntroductionItem extends Omit<React.HTMLAttributes<HTMLDivElement>, 'title'> {
  title?: React.ReactNode;
  desc?: React.ReactNode;
  tag?: React.ReactNode;
  startColor?: string;
  endColor?: string;
  icon?: string;
  to?: LinkProps['to'];
  header?: React.ReactNode;
}

interface IntroductionProps extends ContainerProps {
  column?: number;
  items?: IntroductionItem[];
  cardStyle?: React.CSSProperties;
}

const Introduction: React.FC<IntroductionProps> = (props) => {
  const { styles } = useStyle();

  return (
    <Container className={styles.container} title={props.title} desc={props.desc}>
      <div
        className={styles.content}
        style={{
          gridTemplateColumns: `repeat(${props.column || props.items?.length}, 1fr)`,
        }}
      >
        {props.items?.map((item) => {
          const itemChildren = (
            <>
              {item.header && (
                <div className={styles.item_header}>
                  <CustomizationProvider>{item.header}</CustomizationProvider>
                </div>
              )}
              <div className={styles.item_content}>
                {item.icon && <img className={styles.item_icon} src={item.icon} alt={item.icon} />}
                <div>
                  <h3 className={styles.item_title}>
                    {item.title}
                    {item.tag && (
                      <span
                        className={styles.item_tag}
                        style={{
                          background: `linear-gradient(127deg, ${item.startColor || '#fff'} 23%, ${item.endColor || '#fff'} 100%)`,
                          WebkitBackgroundClip: 'text',
                        }}
                      >
                        {item.tag}
                      </span>
                    )}
                  </h3>
                  <p className={styles.item_desc}>{item.desc}</p>
                </div>
              </div>
            </>
          );
          // 如果 to 是以 http 开头，使用 <a> 标签而不是 <Link>
          if (item.to && typeof item.to === 'string' && item.to.startsWith('http')) {
            return (
              <a
                className={styles.item}
                key={`${item.title}`}
                style={props.cardStyle}
                href={item.to}
                target="_blank"
                rel="noopener noreferrer"
              >
                {itemChildren}
              </a>
            );
          }
          if (item.to) {
            return (
              <Link
                className={styles.item}
                key={`${item.title}`}
                style={props.cardStyle}
                to={item.to}
              >
                {itemChildren}
              </Link>
            );
          }
          return (
            <div className={styles.item} key={`${item.title}`} style={props.cardStyle}>
              {itemChildren}
            </div>
          );
        })}
      </div>
    </Container>
  );
};

export default Introduction;

